INSERT INTO w_config_email
(id, ds_name_parameter, ds_value, ds_parameter_description, ds_last_user_modifier, dt_last_modification, ds_creation_user, dt_creation_date, fg_active)
VALUES(6, 'layoutOlvidePass', '<html><head> <title>Email</title> </head><body><center style="margin-top: 50px;"><img src="cid:image"/></center>             <div style="align-items: center; display: flex; justify-content:center; margin-top: 20px; font-size: 14px; font-family: Arial;">             <center style=" width: 340px; text-align: justify">¡Hola!<br> Recibimos la petición para cambiar tu contraseña.Solo haz clic en el siguiente botón y sigue las instrucciones:</center>             </div>< center style="margin: 50px;">< button style="background-color: #1099d6; width: 250px;height: 40px; margin: auto; border-style: none; color: white; font-family: Arial; font-size: 18px;">Restablecer Contraseña</button></center>             <div style="align-items: center; display: flex; justify-content: center; font-size: 14px; font-family: Arial;">< center style="width: 340px;">Si no haz solicitado el cambio de contraseña,             <br> !no te preocupes¡, solo haz caso omiso de este email. No es necesario responder a este email</center></div ></body></html>', 'Layout para email de olvide mi contraseña', 'rhtotal', '2018-09-10 18:23:14.047', 'rhtotal', '2018-09-10 18:23:14.047', 'true');
INSERT INTO w_config_email
(id, ds_name_parameter, ds_value, ds_parameter_description, ds_last_user_modifier, dt_last_modification, ds_creation_user, dt_creation_date, fg_active)
VALUES(7, 'layoutConfirmCambioPass', '<html><head><title>Email</title></head><body><center style="margin-top: 50px;"><img src="cid:image" /></center>            <div style="align-items: center; display: flex; justify-content:center; margin-top: 20px; font-size: 14px; font-family: Arial;"><center style=" width: 340px; text-align: justify">Estimado :nombre            <br> Acaba de cambiar la contraseña</center></div><div style="align-items: center; display: flex; justify-content: center; font-size: 14px; font-family: Arial;"><center style=" width: 340px;text-align: justify">            <br><br>Si no haz solicitado el cambio de contraseña, llamenos inmediatamente al teléfono :telefono<br><br><br></center></div>            <div style="align-items: center; display: flex; justify-content: center; font-size: 14px; font-family: Arial;"><center style=" width: 340px;text-align: justify">Recuerde :            <br> No comparta nunca sus contraseñas con otras personas. Defina contraseñas dificiles de adivinar y nunca utilice información personal.<br>Asegurese de incluir letras mayúsculas y minúsculas números y simbolos.            <br><br><br></center></div><div style="align-items: center; display: flex; justify-content: center; font-size: 14px; font-family: Arial;"><center style=" width: 340px;text-align: justify">            <br> Utilice contraseñas diferentes para cada cuenta en Internet<br><br>Atte: Unbound</center></div><br></body></html>', 'Layout para email de confirmación de cambio de password', 'rhtotal', '2018-09-10 18:23:14.047', 'rhtotal', '2018-09-10 18:23:14.047', 'true');
INSERT INTO w_config_email
(id, ds_name_parameter, ds_value, ds_parameter_description, ds_last_user_modifier, dt_last_modification, ds_creation_user, dt_creation_date, fg_active)
VALUES(8, 'layoutCodigoRegistro', '<html><head><title>Email</title></head><body><center style="margin-top: 50px;"><img src="cid:image" /></center>            <div style="align-items: center; display: flex; justify-content:center; margin-top: 20px; font-size: 14px; font-family: Arial;"><center style=" width: 340px; text-align: justify">¡Hola!            <br> Para terminar el registro de su cuenta Unbound, debe registrar el siguiente código en la aplicación.</center></div>            <center style="margin: 50px;">Código: :codigo</center><div style="align-items: center; display: flex; justify-content: center; font-size: 14px; font-family: Arial;">            <center style=" width: 340px;">Si no haz solicitado el registro en la app UNBOUND<br> ¡No te preocupes!, solo haz caso omiso de este email. No es necesario responder a este email</center></div></body></html>', 'Layout para email de registro de app', 'rhtotal', '2018-09-10 18:23:14.047', 'rhtotal', '2018-09-10 18:23:14.047', 'true');
INSERT INTO w_config_email
(id, ds_name_parameter, ds_value, ds_parameter_description, ds_last_user_modifier, dt_last_modification, ds_creation_user, dt_creation_date, fg_active)
VALUES(9, 'layoutSeguro', '<html><head><title>Email</title></head><body><center style="margin-top: 50px;"><img src="cid:image" /></center>            <div style="align-items: center; display: flex; justify-content:center; margin-top: 20px; font-size: 14px; font-family: Arial;"><center style=" width: 340px; text-align: justify">Estimado :nombre            <br>El usuario con los datos a continuación listados ha solicitado información de seguros.</center></div><div style="align-items: center; display: flex; justify-content: center; font-size: 14px; font-family: Arial;">            <center style=" width: 340px;text-align: justify"><br>Email: :usuario<br>Nombre: :nombre<br>Apellido Paterno: :apellidoPat<br>Apellido Materno: :apellidoMat<br>Teléfono: :telefono<br><br></center></div>            <div style="align-items: center; display: flex; justify-content: center; font-size: 14px; font-family: Arial;"><center style=" width: 340px;text-align: justify"><br>Saludos!</center></div><br></body></html>', 'Layout para email de solicitud de información de seguro', 'rhtotal', '2018-09-10 18:23:14.047', 'rhtotal', '2018-09-10 18:23:14.047', 'true');
INSERT INTO w_config_email
(id, ds_name_parameter, ds_value, ds_parameter_description, ds_last_user_modifier, dt_last_modification, ds_creation_user, dt_creation_date, fg_active)
VALUES(10, 'layoutNewUser', '<html><head><title>Email</title></head><body><center style="margin-top: 50px;"><img src="cid:image" /></center>
<div style="align-items: center; display: flex; justify-content:center; margin-top: 20px; font-size: 14px; font-family: Arial;">
<center style=" width: 340px; text-align: justify"> Bienvenido a la aplicaci&oacute;n Unbound, has sido registrado por un Administrador
y es necesario que captures tu contrase&ntilde;a, para ello ingresa al Aplicativo Web Unbound y registra la siguiente informaci&oacute;n:<br><br><br><b>Usuraio:</b> :paramUser<br>
<b>Password:</b> :paramPass</center></div><div style="align-items: center; display: flex; justify-content:center; margin-top: 20px; font-size: 14px; font-family: Arial;">
<center style=" width: 340px; text-align: justify">Por seguridad la primera vez que ingrese, se deber&aacute; modificar la contrase&ntilde;a<br><br><br></center>
</div><div style="align-items: center; display: flex; justify-content: center; font-size: 14px; font-family: Arial;"><center style="width: 340px;">
Atte<br>Unbound<br></center></div></body></html>', 'Layout para email de solicitud de información de seguro', 'rhtotal', '2018-09-10 18:23:14.047', 'rhtotal', '2018-09-10 18:23:14.047', 'true');
